public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int i = 0;
    while (i < str.length()) {
        char ch = str.charAt(i);
        if (ch == '\\' && i + 1 < str.length()) {
            char nextCh = str.charAt(i + 1);
            switch (nextCh) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append('\\').append(nextCh);
                    break;
            }
            i += 2;
        } else {
            sb.append(ch);
            i++;
        }
    }
    return sb.toString();
}

